mapper.select:
SELECT MIN(t.id) AS id, t.bus_no AS busNo, t.status_enum AS statusEnum, t.created_by AS createdBy, creator.name AS createdByName, MIN(t.created_at) AS createdAt, t.purpose_location_id AS warehouseId, o.name AS warehouseName, o.name AS stocktakePharmacy, IFNULL(SUM(t.total_price), 0) AS totalPrice, IFNULL(SUM(t.profit_loss_price), 0) AS profitLossPrice, t.applicant_id AS applicantId, app.name AS applicantName, t.apply_time AS applyTime, t.approver_id AS approverId, appr.name AS approverName, t.approval_time AS approvalTime FROM wkf_supply_request t LEFT JOIN adm_organization o ON o.id = t.purpose_location_id AND o.is_deleted = 0 LEFT JOIN adm_practitioner creator ON creator.id = t.created_by AND creator.is_deleted = 0 LEFT JOIN adm_practitioner app ON app.id = t.applicant_id AND app.is_deleted = 0 LEFT JOIN adm_practitioner appr ON appr.id = t.approver_id AND appr.is_deleted = 0 WHERE t.is_deleted = 0 AND t.type_enum IN ('INVENTORY_CHECK', 'PHARMACY_STOCKTAKE', 'CABINET_STOCKTAKE')
AND t.bus_no LIKE CONCAT('%', #{busNo}, '%')
AND t.status_enum = #{statusEnum}
AND t.purpose_location_id = #{warehouseId}
AND o.name LIKE CONCAT('%', #{warehouseName}, '%')
AND t.applicant_id = #{applicantId}
AND t.created_at >= #{startTime}
AND t.created_at <= #{endTime}
GROUP BY t.bus_no, t.status_enum, t.created_by, creator.name, t.purpose_location_id, o.name, t.applicant_id, app.name, t.approver_id, appr.name, t.apply_time, t.approval_time ORDER BY MIN(t.created_at) DESC, t.bus_no DESC

mapper.update:
UPDATE wkf_supply_request SET status_enum = #{statusEnum}, applicant_id = #{applicantId}, apply_time = #{applyTime},
remake = #{remark},
updated_by = #{updatedBy}, updated_at = #{updatedAt}, version = version + 1 WHERE is_deleted = 0 AND type_enum IN ('INVENTORY_CHECK', 'PHARMACY_STOCKTAKE', 'CABINET_STOCKTAKE') AND bus_no = #{busNo}
